_IDX = {lang: i for i, lang in enumerate(LANGS)}


def _norm(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def ui_para(lang: str) -> dict:
    """Diccionario y patrones para el idioma pedido (vacío en español o idioma desconocido)."""
    i = _IDX.get(lang)
    if i is None:
        return {"lang": lang, "map": {}, "patterns": []}
    return {
        "lang": lang,
        "map": {_norm(k): v[i] for k, v in UI.items()},
        "patterns": [[rx, tpl[i]] for rx, tpl in PATTERNS],
    }
